DECLARE @B bigint=(SELECT BatchId FROM ssis_flow.Context),@Previous bigint=(SELECT PreviousVersion FROM ssis_flow.Context),@Next bigint=(SELECT NextVersion FROM ssis_flow.Context);
IF @Previous IS NULL BEGIN
INSERT etl_raw.[SalesOrderDetail]([SalesOrderID],[SalesOrderDetailID],[CarrierTrackingNumber],[OrderQty],[ProductID],[SpecialOfferID],[UnitPrice],[UnitPriceDiscount],[LineTotal],[rowguid],[ModifiedDate],LoadBatchID) SELECT S.[SalesOrderID],S.[SalesOrderDetailID],S.[CarrierTrackingNumber],S.[OrderQty],S.[ProductID],S.[SpecialOfferID],S.[UnitPrice],S.[UnitPriceDiscount],S.[LineTotal],S.[rowguid],S.[ModifiedDate],@B FROM ssis_flow.Delta_SalesOrderDetail S;
INSERT stg.[SalesOrderDetail]([SalesOrderID],[SalesOrderDetailID],[CarrierTrackingNumber],[OrderQty],[ProductID],[SpecialOfferID],[UnitPrice],[UnitPriceDiscount],[LineTotal],[rowguid],[ModifiedDate],LoadBatchID) SELECT [SalesOrderID],[SalesOrderDetailID],[CarrierTrackingNumber],[OrderQty],[ProductID],[SpecialOfferID],[UnitPrice],[UnitPriceDiscount],[LineTotal],[rowguid],[ModifiedDate],@B FROM etl_raw.[SalesOrderDetail];
INSERT etl_v2.SourceChange SELECT @B,N'Sales.SalesOrderDetail','I',@Next,(SELECT R.[SalesOrderID],R.[SalesOrderDetailID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),NULL FROM etl_raw.[SalesOrderDetail] R;
END ELSE BEGIN
SELECT [SalesOrderID],[SalesOrderDetailID],CONVERT(char(1),FlowOperation) SYS_CHANGE_OPERATION,FlowVersion SYS_CHANGE_VERSION INTO #CT_SalesOrderDetail FROM ssis_flow.Delta_SalesOrderDetail;
INSERT etl_v2.SourceChange SELECT @B,N'Sales.SalesOrderDetail',C.SYS_CHANGE_OPERATION,C.SYS_CHANGE_VERSION,(SELECT C.[SalesOrderID],C.[SalesOrderDetailID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),(SELECT R.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) FROM #CT_SalesOrderDetail C LEFT JOIN etl_raw.[SalesOrderDetail] R ON R.[SalesOrderID]=C.[SalesOrderID] AND R.[SalesOrderDetailID]=C.[SalesOrderDetailID];
DELETE R FROM etl_raw.[SalesOrderDetail] R JOIN #CT_SalesOrderDetail C ON R.[SalesOrderID]=C.[SalesOrderID] AND R.[SalesOrderDetailID]=C.[SalesOrderDetailID] WHERE C.SYS_CHANGE_OPERATION='D';
UPDATE R SET R.[CarrierTrackingNumber]=S.[CarrierTrackingNumber],R.[OrderQty]=S.[OrderQty],R.[ProductID]=S.[ProductID],R.[SpecialOfferID]=S.[SpecialOfferID],R.[UnitPrice]=S.[UnitPrice],R.[UnitPriceDiscount]=S.[UnitPriceDiscount],R.[LineTotal]=S.[LineTotal],R.[rowguid]=S.[rowguid],R.[ModifiedDate]=S.[ModifiedDate],R.LoadBatchID=@B FROM etl_raw.[SalesOrderDetail] R JOIN #CT_SalesOrderDetail C ON R.[SalesOrderID]=C.[SalesOrderID] AND R.[SalesOrderDetailID]=C.[SalesOrderDetailID] JOIN ssis_flow.Delta_SalesOrderDetail S ON S.[SalesOrderID]=C.[SalesOrderID] AND S.[SalesOrderDetailID]=C.[SalesOrderDetailID] WHERE C.SYS_CHANGE_OPERATION<>'D';
INSERT etl_raw.[SalesOrderDetail]([SalesOrderID],[SalesOrderDetailID],[CarrierTrackingNumber],[OrderQty],[ProductID],[SpecialOfferID],[UnitPrice],[UnitPriceDiscount],[LineTotal],[rowguid],[ModifiedDate],LoadBatchID) SELECT S.[SalesOrderID],S.[SalesOrderDetailID],S.[CarrierTrackingNumber],S.[OrderQty],S.[ProductID],S.[SpecialOfferID],S.[UnitPrice],S.[UnitPriceDiscount],S.[LineTotal],S.[rowguid],S.[ModifiedDate],@B FROM #CT_SalesOrderDetail C JOIN ssis_flow.Delta_SalesOrderDetail S ON S.[SalesOrderID]=C.[SalesOrderID] AND S.[SalesOrderDetailID]=C.[SalesOrderDetailID] WHERE C.SYS_CHANGE_OPERATION<>'D' AND NOT EXISTS(SELECT 1 FROM etl_raw.[SalesOrderDetail] R WHERE R.[SalesOrderID]=S.[SalesOrderID] AND R.[SalesOrderDetailID]=S.[SalesOrderDetailID]);
INSERT stg.[SalesOrderDetail]([SalesOrderID],[SalesOrderDetailID],[CarrierTrackingNumber],[OrderQty],[ProductID],[SpecialOfferID],[UnitPrice],[UnitPriceDiscount],[LineTotal],[rowguid],[ModifiedDate],LoadBatchID) SELECT R.[SalesOrderID],R.[SalesOrderDetailID],R.[CarrierTrackingNumber],R.[OrderQty],R.[ProductID],R.[SpecialOfferID],R.[UnitPrice],R.[UnitPriceDiscount],R.[LineTotal],R.[rowguid],R.[ModifiedDate],@B FROM etl_raw.[SalesOrderDetail] R JOIN #CT_SalesOrderDetail C ON R.[SalesOrderID]=C.[SalesOrderID] AND R.[SalesOrderDetailID]=C.[SalesOrderDetailID] WHERE C.SYS_CHANGE_OPERATION<>'D';
END;